<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { http, errorMessage } from '../../api/http'; import type { Page, Order } from '../../types'; import { money, dateTime } from '../../utils/format'; import Pagination from '../../components/Pagination.vue'; import StatusBadge from '../../components/StatusBadge.vue'; import LoadingState from '../../components/LoadingState.vue'
const filters = reactive({ search: '', orderStatus: '', paymentStatus: '', from: '', to: '' }), result = ref<Page<Order>>(), loading = ref(true), error = ref(''); async function load(page = 1) { loading.value = true; error.value = ''; try { result.value = (await http.get<Page<Order>>('/admin/orders', { params: { ...filters, page } })).data } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } } onMounted(() => load())
</script>
<template><span class="eyebrow">THEO DÕI TỪNG HÀNH TRÌNH</span><h1>Quản lý đơn hàng</h1><p class="muted">Lọc ngày theo ngày đặt đơn và múi giờ Việt Nam.</p><section class="panel"><form class="toolbar" @submit.prevent="load()"><input v-model="filters.search" aria-label="Tìm đơn" placeholder="Mã đơn, tên hoặc email người mua"><select v-model="filters.orderStatus" aria-label="Trạng thái đơn"><option value="">Tất cả trạng thái đơn</option><option value="Pending">Đang xử lý</option><option value="Shipping">Đang giao</option><option value="Completed">Hoàn thành</option><option value="Cancelled">Đã hủy</option></select><select v-model="filters.paymentStatus" aria-label="Trạng thái thanh toán"><option value="">Mọi thanh toán</option><option value="Unpaid">Chưa thanh toán</option><option value="Paid">Đã thanh toán</option><option value="Failed">Thanh toán lỗi</option></select><label>Từ ngày<input v-model="filters.from" type="date"></label><label>Đến ngày<input v-model="filters.to" type="date"></label><button class="btn">Lọc đơn</button><button type="button" class="btn secondary" @click="Object.assign(filters, { search: '', orderStatus: '', paymentStatus: '', from: '', to: '' }); load()">Xóa lọc</button></form><p v-if="error" class="alert error">{{ error }}</p><LoadingState v-if="loading" /><template v-else><p class="muted">{{ result?.totalItems || 0 }} đơn hàng</p><div class="table-wrap"><table><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Ngày đặt (VN)</th><th>Tổng tiền</th><th>Đơn hàng</th><th>Thanh toán</th><th></th></tr></thead><tbody><tr v-for="o in result?.items" :key="o.id"><td>{{ o.orderCode }}</td><td>{{ o.buyerName || o.recipientName }}</td><td>{{ dateTime(o.createdAt) }}</td><td>{{ money(o.totalAmount) }}</td><td><StatusBadge :status="o.orderStatus" /></td><td><StatusBadge :status="o.paymentStatus" /></td><td><RouterLink :to="`/admin/orders/${o.id}`" class="text-link">Xử lý →</RouterLink></td></tr><tr v-if="!result?.totalItems"><td colspan="7">Không có đơn hàng phù hợp.</td></tr></tbody></table></div><Pagination v-if="result" :page="result.page" :total-pages="result.totalPages" @change="load" /></template></section></template>